// 最小 React 桩：只实现插件用到的 useState/useEffect/useRef，
// 外加一个测试驱动 createRoot（真实 React 只做同样的事：渲染 -> 冲刷 effect -> 重渲染）。

let current = null

const slot = () => {
  const ctx = current
  const index = ctx.cursor
  ctx.cursor += 1

  return [ctx, index]
}

export function useState(initial) {
  const [ctx, index] = slot()

  if (!(index in ctx.state)) {
    ctx.state[index] = typeof initial === 'function' ? initial() : initial
  }

  const set = next => {
    const value = typeof next === 'function' ? next(ctx.state[index]) : next

    if (Object.is(value, ctx.state[index])) {
      return
    }

    ctx.state[index] = value
    ctx.dirty = true
  }

  return [ctx.state[index], set]
}

export function useRef(initial) {
  const [ctx, index] = slot()

  if (!(index in ctx.refs)) {
    ctx.refs[index] = { current: initial }
  }

  return ctx.refs[index]
}

export function useEffect(fn) {
  const ctx = current
  ctx.cursor += 1

  // 只在挂载那一趟登记，之后的重渲染不重跑（依赖数组在桩里恒为空）。
  if (!ctx.mounted) {
    ctx.effects.push(fn)
  }
}

export function createRoot(element) {
  const ctx = { cleanups: [], cursor: 0, dirty: false, effects: [], mounted: false, refs: {}, state: {} }
  let output = null

  const pass = () => {
    ctx.cursor = 0
    ctx.dirty = false
    const prev = current
    current = ctx

    try {
      output = element.type(element.props)
    } finally {
      current = prev
    }

    if (!ctx.mounted) {
      ctx.mounted = true

      for (const fn of ctx.effects.splice(0)) {
        const cleanup = fn()

        if (typeof cleanup === 'function') {
          ctx.cleanups.push(cleanup)
        }
      }
    }
  }

  pass()

  return {
    ctx,
    get output() {
      return output
    },
    /** 把已排队的同步 setState 冲刷干净（测试里在 await 一个 tick 之后调用）。 */
    rerender() {
      let guard = 0

      while (ctx.dirty && guard < 50) {
        guard += 1
        pass()
      }
    },
    unmount() {
      for (const fn of ctx.cleanups.splice(0)) {
        fn()
      }
    }
  }
}
